import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import Database from 'better-sqlite3';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import * as schema from './schema';

/**
 * Generated by `npm run db:generate`. Resolved against the working directory,
 * so the server must be started from the project root (or `/app` in the image).
 */
export const MIGRATIONS_FOLDER = resolve('drizzle');

/** Opens (and creates, if needed) the SQLite database at `path`. */
export function openDatabase(path: string) {
	if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });

	const client = new Database(path);
	client.pragma('journal_mode = WAL');
	client.pragma('foreign_keys = ON');

	return drizzle(client, { schema });
}

export type Db = ReturnType<typeof openDatabase>;

/** Applies every migration in `migrationsFolder` that hasn't run yet. */
export function migrateDatabase(db: Db, migrationsFolder = MIGRATIONS_FOLDER): void {
	migrate(db, { migrationsFolder });
}
